import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../repositories/providers.dart';
class RentalsScreen extends ConsumerWidget{const RentalsScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Rentals')),body:ListView(padding:const EdgeInsets.all(16),children:[const TextField(decoration:InputDecoration(hintText:'Search by city, price or type')),for(final r in ref.watch(mockRepositoryProvider).rentals()) ZayloCard(child:ListTile(title:Text(r.title),subtitle:Text('${r.city} • ${r.type} • Contact ${r.contact}'),trailing:Column(mainAxisSize:MainAxisSize.min,children:[Text('\$${r.price.toStringAsFixed(0)}'),TrustBadge(r.verified)]),onTap:()=>showComingSoon(context,'Contact advertiser/report listing')))]));}
